-- Lab XMPP server for TR-069 Annex K XMPP Connection Request
-- (docs/XMPP-CONNECTION-REQUEST.md). Its only job: CPEs behind CGNAT hold
-- an outbound c2s session here, and the ACS (cmd/api) sends them the Annex K
-- connectionRequest iq through it. Everything a chat server would add —
-- server-to-server, in-band registration, HTTP, MUC, offline storage of
-- messages for the world — is off.
--
-- Values come from the environment (docker-compose.yml, generated by
-- scripts/gen-env.sh); the entrypoint (prosody-entrypoint.sh) creates the
-- ACS account from ACS_XMPP_USER/ACS_XMPP_PASSWORD on every start.

local domain = Lua.os.getenv("ACS_XMPP_DOMAIN") or "xmpp.acs.lab"
local acs_user = Lua.os.getenv("ACS_XMPP_USER") or "acs"

-- The ACS account is the only admin: XEP-0133 (mod_admin_adhoc) lets it
-- create one account per CPE over its existing session during zero-touch
-- provisioning — no docker socket, shell access or HTTP admin API needed.
admins = { acs_user .. "@" .. domain }

modules_enabled = {
	"roster"; -- required by the c2s core
	"saslauth";
	"tls";
	"disco";
	"ping"; -- XEP-0199: the ACS and CPEs keep their sessions alive with it
	"adhoc"; -- XEP-0050, needed by admin_adhoc
	"admin_adhoc"; -- XEP-0133 add-user / change-user-password for the ACS
}
modules_disabled = {
	"s2s"; -- no federation: only CPEs and the ACS ever talk to this server
	"offline";
}

allow_registration = false
authentication = "internal_hashed" -- SCRAM-SHA-1 and PLAIN (inside TLS only)
storage = "internal"
data_path = "/var/lib/prosody"
pidfile = "/var/run/prosody/prosody.pid"

-- TLS is mandatory for every client: the Annex K stanza carries the CPE's
-- Connection Request password.
c2s_require_encryption = true
c2s_ports = { 5222 }
c2s_interfaces = { "*" }
-- The entrypoint copies the certificate (self-signed from
-- scripts/xmpp-cert.sh, or an operator-supplied one mounted at /certs) here
-- so the prosody user can read the key without loosening host permissions.
ssl = {
	certificate = "/var/lib/prosody/acs-certs/xmpp.crt";
	key = "/var/lib/prosody/acs-certs/xmpp.key";
}

-- Rough per-connection inbound limit: a CPE only ever answers iqs and pings.
limits = {
	c2s = { rate = "10kb/s"; burst = "2s" };
}

log = { info = "*console" } -- docker logs

VirtualHost (domain)
